48		public String unescapeString(String str) {
49			int len = str.length();
50			if (len == 0) {
51				return "\"\"";
52			}
53			StringBuilder res = new StringBuilder();
54			res.append('"');
55			visitCodePoints(str, codePoint -> processCodePoint(codePoint, res));
56			res.append('"');
57			return res.toString();
58		}
59	
60		private void processCodePoint(int codePoint, StringBuilder res) {
61			String str = getSpecialStringForCodePoint(codePoint);
62			if (str != null) {
63				res.append(str);
64				return;
65			}
66			if (isEscapeNeededForCodePoint(codePoint)) {
67				res.append("\\u").append(String.format("%04x", codePoint));
68			} else {
69				res.appendCodePoint(codePoint);
70			}
71		}
72	
73		private boolean isEscapeNeededForCodePoint(int codePoint) {
74			if (codePoint < 32) {
75				return true;
76			}
77			if (codePoint < 127) {
78				return false;
79			}
80			if (escapeUnicode) {
81				return true;
82			}
83			return !NameMapper.isPrintableCodePoint(codePoint);
84		}
