111		@Nullable
112		private String getSpecialStringForCodePoint(int c) {
113			switch (c) {
114				case '\n':
115					return "\\n";
116				case '\r':
117					return "\\r";
118				case '\t':
119					return "\\t";
120				case '\b':
121					return "\\b";
122				case '\f':
123					return "\\f";
124				case '\'':
125					return "'";
126				case '"':
127					return "\\\"";
128				case '\\':
129					return "\\\\";
130	
131				default:
132					return null;
133			}
134		}
