185		public static String escapeResValue(String str) {
186			int len = str.length();
187			StringBuilder sb = new StringBuilder(len);
188			for (int i = 0; i < len; i++) {
189				char c = str.charAt(i);
190				commonEscapeAndAppend(sb, c);
191			}
192			return sb.toString();
193		}
