195		public static String escapeResStrValue(String str) {
196			int len = str.length();
197			StringBuilder sb = new StringBuilder(len);
198			for (int i = 0; i < len; i++) {
199				char c = str.charAt(i);
200				switch (c) {
201					case '"':
202						sb.append("\\\"");
203						break;
204					case '\'':
205						sb.append("\\'");
206						break;
207					default:
208						commonEscapeAndAppend(sb, c);
209						break;
210				}
211			}
212			return sb.toString();
213		}
