215		private static @Nullable String escapeXmlChar(char c) {
216			if (c <= 0x1F) {
217				return "\\" + (int) c;
218			}
219			switch (c) {
220				case '&':
221					return "&amp;";
222				case '<':
223					return "&lt;";
224				case '>':
225					return "&gt;";
226				case '"':
227					return "&quot;";
228				case '\'':
229					return "&apos;";
230				case '\\':
231					return "\\\\";
232				default:
233					return null;
234			}
235		}
