254		private static void commonEscapeAndAppend(StringBuilder sb, char c) {
255			String replace = escapeWhiteSpaceChar(c);
256			if (replace == null) {
257				replace = escapeXmlChar(c);
258			}
259			if (replace != null) {
260				sb.append(replace);
261			} else {
262				sb.append(c);
263			}
264		}
