278		public static int countMatches(String str, String subStr) {
279			if (str == null || str.isEmpty() || subStr == null || subStr.isEmpty()) {
280				return 0;
281			}
282			int subStrLen = subStr.length();
283			int count = 0;
284			int idx = 0;
285			while ((idx = str.indexOf(subStr, idx)) != -1) {
286				count++;
287				idx += subStrLen;
288			}
289			return count;
290		}
