296		public static String removeChar(String str, char ch) {
297			int pos = str.indexOf(ch);
298			if (pos == -1) {
299				return str;
300			}
301			StringBuilder sb = new StringBuilder(str.length());
302			int cur = 0;
303			int next = pos;
304			while (true) {
305				sb.append(str, cur, next);
306				cur = next + 1;
307				next = str.indexOf(ch, cur);
308				if (next == -1) {
309					sb.append(str, cur, str.length());
310					break;
311				}
312			}
313			return sb.toString();
314		}
