374		public static List<String> splitByFixedString(String content, String splitStr) {
375			if (isEmpty(content)) {
376				return Collections.emptyList();
377			}
378			List<String> parts = new ArrayList<>();
379			int splitLen = splitStr.length();
380			int pos = 0;
381			while (true) {
382				int split = content.indexOf(splitStr, pos);
383				if (split == -1) {
384					parts.add(content.substring(pos));
385					return parts;
386				}
387				parts.add(content.substring(pos, split));
388				pos = split + splitLen;
389			}
390		}
