411		private String formatNumber(long number, int bytesLen, boolean cast) {
412			String numStr;
413			if (integerFormat.isHexadecimal()) {
414				String hexStr = Long.toHexString(number);
415				if (number < 0) {
416					// cut leading 'f' for negative numbers to match number type length
417					int len = hexStr.length();
418					numStr = "0x" + hexStr.substring(len - bytesLen * 2, len);
419					// force cast, because unsigned negative numbers are bigger
420					// than signed max value allowed by compiler
421					cast = true;
422				} else {
423					numStr = "0x" + hexStr;
424				}
425			} else {
426				numStr = Long.toString(number);
427			}
428			if (bytesLen == 8 && (number == Long.MIN_VALUE || Math.abs(number) >= Integer.MAX_VALUE)) {
429				// force cast for long values bigger than min/max int
430				// to resolve compiler error: "integer number too large"
431				cast = true;
432			}
433			if (cast) {
434				if (bytesLen == 8) {
435					return numStr + 'L';
436				}
437				return getCastStr(bytesLen) + numStr;
438			}
439			return numStr;
440		}
441	
442		private static String getCastStr(int bytesLen) {
443			switch (bytesLen) {
444				case 1:
445					return "(byte) ";
446				case 2:
447					return "(short) ";
448				case 4:
449					return "(int) ";
450				case 8:
451					return "(long) ";
452				default:
453					throw new JadxRuntimeException("Unexpected number type length: " + bytesLen);
454			}
455		}
456	
457		public String formatByte(long l, boolean cast) {
458			return formatNumber(l, 1, cast);
459		}
