461		public String formatShort(long l, boolean cast) {
462			if (integerFormat == IntegerFormat.AUTO) {
463				switch ((short) l) {
464					case Short.MAX_VALUE:
465						return "Short.MAX_VALUE";
466					case Short.MIN_VALUE:
467						return "Short.MIN_VALUE";
468				}
469			}
470			return formatNumber(l, 2, cast);
471		}
