473		public String formatInteger(long l, boolean cast) {
474			if (integerFormat == IntegerFormat.AUTO) {
475				switch ((int) l) {
476					case Integer.MAX_VALUE:
477						return "Integer.MAX_VALUE";
478					case Integer.MIN_VALUE:
479						return "Integer.MIN_VALUE";
480				}
481			}
482			return formatNumber(l, 4, cast);
483		}
