485		public String formatLong(long l, boolean cast) {
486			if (integerFormat == IntegerFormat.AUTO) {
487				if (l == Long.MAX_VALUE) {
488					return "Long.MAX_VALUE";
489				}
490				if (l == Long.MIN_VALUE) {
491					return "Long.MIN_VALUE";
492				}
493			}
494			return formatNumber(l, 8, cast);
495		}
