497		public static String formatDouble(double d) {
498			if (Double.isNaN(d)) {
499				return "Double.NaN";
500			}
501			if (d == Double.NEGATIVE_INFINITY) {
502				return "Double.NEGATIVE_INFINITY";
503			}
504			if (d == Double.POSITIVE_INFINITY) {
505				return "Double.POSITIVE_INFINITY";
506			}
507			if (d == Double.MIN_VALUE) {
508				return "Double.MIN_VALUE";
509			}
510			if (d == Double.MAX_VALUE) {
511				return "Double.MAX_VALUE";
512			}
513			if (d == Double.MIN_NORMAL) {
514				return "Double.MIN_NORMAL";
515			}
516			return Double.toString(d) + 'd';
517		}
