528			}
529			if (f == Float.MIN_VALUE) {
530				return "Float.MIN_VALUE";
531			}
532			if (f == Float.MAX_VALUE) {
533				return "Float.MAX_VALUE";
534			}
535			if (f == Float.MIN_NORMAL) {
536				return "Float.MIN_NORMAL";
537			}
538			return Float.toString(f) + 'f';
539		}
