53		public static <T, U> boolean orderedEquals(List<T> list1, List<U> list2, BiPredicate<T, U> comparer) {
54			if (list1 == list2) {
55				return true;
56			}
57			if (list1.size() != list2.size()) {
58				return false;
59			}
60			Iterator<T> iter1 = list1.iterator();
61			Iterator<U> iter2 = list2.iterator();
62			while (iter1.hasNext() && iter2.hasNext()) {
63				T item1 = iter1.next();
64				U item2 = iter2.next();
65				if (!comparer.test(item1, item2)) {
66					return false;
67				}
68			}
69			return !iter1.hasNext() && !iter2.hasNext();
70		}
