191			if (list == null || list.isEmpty()) {
192				return Collections.emptyList();
193			}
194			List<T> result = new ArrayList<>();
195			for (T element : list) {
196				if (filter.test(element)) {
197					result.add(element);
198				}
199			}
200			return result;
201		}
