210			if (list == null || list.isEmpty()) {
211				return null;
212			}
213			T found = null;
214			for (T element : list) {
215				if (filter.test(element)) {
216					if (found != null) {
217						// found second
218						return null;
219					}
220					found = element;
221				}
222			}
223			return found;
