275		public static void appendStackTrace(ICodeWriter code, Throwable throwable) {
276			if (throwable == null) {
277				return;
278			}
279			code.startLine();
280			OutputStream w = new OutputStream() {
281				@Override
282				public void write(int b) {
283					char c = (char) b;
284					switch (c) {
285						case '\n':
286							code.startLine();
287							break;
288	
289						case '\r':
290							// ignore
291							break;
292	
293						default:
294							code.add(c);
295							break;
296					}
297				}
298			};
299			try (PrintWriter pw = new PrintWriter(w, true, StandardCharsets.UTF_8)) {
300				filterRecursive(throwable);
301				throwable.printStackTrace(pw);
302				pw.flush();
303			}
304		}
