318		private static void filter(Throwable th) {
319			StackTraceElement[] stackTrace = th.getStackTrace();
320			int length = stackTrace.length;
321			StackTraceElement prevElement = null;
322			for (int i = 0; i < length; i++) {
323				StackTraceElement stackTraceElement = stackTrace[i];
324				String clsName = stackTraceElement.getClassName();
325				if (clsName.equals(STACKTRACE_STOP_CLS_NAME)
326						|| clsName.startsWith(JADX_API_PACKAGE)
327						|| Objects.equals(prevElement, stackTraceElement)) {
328					th.setStackTrace(Arrays.copyOfRange(stackTrace, 0, i));
329					return;
330				}
331				prevElement = stackTraceElement;
332			}
333			// stop condition not found -> just cut tail to any jadx class
334			for (int i = length - 1; i >= 0; i--) {
335				String clsName = stackTrace[i].getClassName();
336				if (clsName.startsWith("jadx.")) {
337					if (clsName.startsWith("jadx.tests.")) {
338						continue;
339					}
340					th.setStackTrace(Arrays.copyOfRange(stackTrace, 0, i));
341					return;
342				}
343			}
344		}
