615		private static final class SimpleThreadFactory implements ThreadFactory {
616			private static final AtomicInteger POOL = new AtomicInteger(0);
617			private static final Thread.UncaughtExceptionHandler EXC_HANDLER = new SimpleUncaughtExceptionHandler();
618	
619			private final AtomicInteger number = new AtomicInteger(0);
620			private final String name;
621	
622			SimpleThreadFactory(String name) {
623				this.name = name;
624			}
625	
626			@Override
627			public Thread newThread(@NotNull Runnable r) {
628				Thread thread = new Thread(r, "jadx-" + name
629						+ '-' + POOL.incrementAndGet()
630						+ '-' + number.incrementAndGet());
631				thread.setUncaughtExceptionHandler(EXC_HANDLER);
632				return thread;
633			}
634	
635			private static class SimpleUncaughtExceptionHandler implements Thread.UncaughtExceptionHandler {
636				private static final Logger LOG = LoggerFactory.getLogger(SimpleUncaughtExceptionHandler.class);
637	
638				@Override
639				public void uncaughtException(Thread thread, Throwable e) {
640					if (e instanceof OutOfMemoryError) {
641						thread.interrupt();
642						LOG.error("OutOfMemoryError in thread: {}, forcing interrupt", thread.getName());
643					} else {
644						LOG.error("Uncaught thread exception, thread: {}", thread.getName(), e);
645					}
646				}
647			}
648		}
