	public static String smaliNameToJavaName(String descString) {
		if (descString.isEmpty()) {
			return descString;
		}

		String javaName;
		switch (descString.charAt(0)) {
			case 'V':
				javaName = "void";
				break;
			case 'Z':
				javaName = "boolean";
				break;
			case 'C':
				javaName = "char";
